import { useState } from 'react';
import { Linkedin, Mail, Github, CheckCircle2, AlertCircle, Download, ArrowUpRight } from 'lucide-react';
import { personalInfo } from '../../data/personalInfo';

export default function Contact() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const FORMSPREE_ENDPOINT = import.meta.env.VITE_FORMSPREE_ENDPOINT || 'https://formspree.io/f/mjykadoy';

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitStatus('idle');

    const formData = new FormData(e.currentTarget);

    try {
      const response = await fetch(FORMSPREE_ENDPOINT, {
        method: 'POST',
        body: formData,
        headers: { 'Accept': 'application/json' },
      });
      if (response.ok) {
        setSubmitStatus('success');
        (e.target as HTMLFormElement).reset();
      } else {
        setSubmitStatus('error');
      }
    } catch {
      setSubmitStatus('error');
    } finally {
      setIsSubmitting(false);
    }
  };

  const socialLinks = [
    { href: personalInfo.githubUrl, icon: Github, label: 'GitHub' },
    { href: personalInfo.linkedInUrl, icon: Linkedin, label: 'LinkedIn' },
    { href: `mailto:${personalInfo.email}`, icon: Mail, label: 'Email' },
  ];

  return (
    <section id="contact" className="py-24 px-6">
      <div className="max-w-5xl mx-auto grid lg:grid-cols-5 gap-12 lg:gap-16">
        <div className="lg:col-span-2">
          <p className="section-label">Contact</p>
          <h2 className="text-3xl sm:text-4xl font-bold tracking-tight mb-4">
            Let&apos;s build something together
          </h2>
          <p className="text-fg-muted mb-6">
            I&apos;m currently open to new consulting engagements. Whether you have
            a project in mind or a question about your infrastructure, I&apos;ll
            get back to you within a day.
          </p>
          <a
            href={`mailto:${personalInfo.email}`}
            className="inline-block text-accent text-lg font-medium underline decoration-accent/40 underline-offset-4 hover:decoration-accent transition-colors"
          >
            {personalInfo.email}
          </a>

          <ul className="mt-10 space-y-2">
            {socialLinks.map(({ href, icon: Icon, label }) => (
              <li key={label}>
                <a
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="group flex items-center gap-3 rounded-card border border-border px-4 py-3 text-sm text-fg-muted hover:text-fg hover:border-border-hover transition-colors"
                >
                  <Icon size={18} aria-hidden="true" className="text-fg-dim group-hover:text-accent transition-colors" />
                  <span className="font-medium">{label}</span>
                  <ArrowUpRight size={16} aria-hidden="true" className="ml-auto text-fg-dim opacity-0 group-hover:opacity-100 transition-opacity" />
                </a>
              </li>
            ))}
          </ul>
        </div>

        <div className="lg:col-span-3">
          <form onSubmit={handleSubmit} className="rounded-card border border-border bg-white/5 backdrop-blur-md p-6 md:p-8 space-y-4" noValidate>
            <div className="space-y-1.5">
              <label htmlFor="name" className="text-sm font-medium text-fg">Name</label>
              <input
                id="name"
                type="text"
                name="name"
                placeholder="Your name"
                autoComplete="name"
                className="input-field"
                required
              />
            </div>
            <div className="space-y-1.5">
              <label htmlFor="email" className="text-sm font-medium text-fg">Email</label>
              <input
                id="email"
                type="email"
                name="email"
                placeholder="you@example.com"
                autoComplete="email"
                className="input-field"
                required
              />
            </div>
            <div className="space-y-1.5">
              <label htmlFor="message" className="text-sm font-medium text-fg">Message</label>
              <textarea
                id="message"
                name="message"
                placeholder="Tell me about your project&hellip;"
                rows={5}
                className="input-field resize-none"
                required
              />
            </div>
            <input
              type="text"
              name="_gotcha"
              tabIndex={-1}
              autoComplete="off"
              aria-hidden="true"
              className="hidden"
            />
            <button
              type="submit"
              disabled={isSubmitting}
              className="btn-primary w-full disabled:opacity-50 cursor-pointer"
            >
              {isSubmitting ? 'Sending&hellip;' : 'Send message'}
            </button>
            {submitStatus === 'success' && (
              <p className="text-sm text-success font-medium flex items-center gap-2 mt-2" role="status" aria-live="polite">
                <CheckCircle2 size={16} aria-hidden="true" />
                Sent. I&apos;ll get back to you soon.
              </p>
            )}
            {submitStatus === 'error' && (
              <p className="text-sm text-destructive flex items-center gap-2 mt-2" role="alert" aria-live="assertive">
                <AlertCircle size={16} aria-hidden="true" />
                Something went wrong. Try again or email me directly.
              </p>
            )}

            <a
              href="/docs/resume.pdf"
              download
              className="btn-secondary inline-flex items-center justify-center gap-2 w-full"
            >
              <Download size={16} />
              Download resume
            </a>
          </form>
        </div>
      </div>
    </section>
  );
}
